{"issue": true, "summary": "The `map` method on the returned generator function incorrectly uses `this` which is not bound to the generator, causing a TypeError when called as `generator.map()`.", "edits": [{"path": "index.js", "old": "		map: {
			async value(iterable, function_) {
				const promises = Array.from(iterable, (value, index) => this(function_, value, index));
				return Promise.all(promises);
			},
		},", "new": "		map: {
			async value(iterable, function_) {
				const promises = Array.from(iterable, (value, index) => generator(function_, value, index));
				return Promise.all(promises);
			},
		},"}]}
